document.addEventListener("DOMContentLoaded",function(){const n=document.getElementById("retaining-wall-form"),e=document.getElementById("retaining-wall-result");n&&n.addEventListener("submit",function(n){n.preventDefault();const t=parseFloat(document.getElementById("wall-length").value),a=parseFloat(document.getElementById("wall-height").value),[i,o,p,l,s]=document.getElementById("wall-block-type").value.split(","),r=document.getElementById("wall-config").value,d=parseFloat(document.getElementById("wall-conditions").value);if(t<=0||a<=0)return e.textContent="Please enter valid dimensions.",void 0;let c=t*a;"corner"===r?c*=1.1:"terraced"===r&&(c*=1.2);const g=Math.ceil(c*parseFloat(l)*d),u=Math.ceil(t*d),v=.5+a/12,$=2+parseFloat(o)/12,h=t*$*v/27,f=t*$*.5/27,m=1*t*a/27,x=t,F=3*t,y=g*parseFloat(s),b=u*(.8*parseFloat(s)),k=35*f,E=40*m,w=8*x,B=1.5*F,C=25*h,q=y+b+k+E+w+B,D=q+C,I=.5*c*d,M=75*I,L=a>3,T=L?1500:0,P=.7*a;e.innerHTML=`\n        <div class="result-section">\n          <h4>Retaining Wall Specifications:</h4>\n          <p>Length: ${t} feet</p>\n          <p>Height: ${a} feet</p>\n          <p>Wall area: ${c.toFixed(1)} sq ft</p>\n          <p>Block type: ${i} (${o}"×${p}")</p>\n          <p>Configuration: ${r.charAt(0).toUpperCase()+r.slice(1)}</p>\n        </div>\n        \n        <div class="result-blocks">\n          <h4>Block Requirements:</h4>\n          <p><strong>${g} wall blocks</strong></p>\n          <p><strong>${u} cap blocks</strong></p>\n          <p>Blocks per sq ft: ${l}</p>\n          <p>Block cost: $${y.toFixed(0)}</p>\n          <p>Cap block cost: $${b.toFixed(0)}</p>\n        </div>\n        \n        <div class="result-foundation">\n          <h4>Foundation & Excavation:</h4>\n          <p>Excavation depth: ${(12*v).toFixed(1)}"</p>\n          <p>Excavation width: ${(12*$).toFixed(1)}"</p>\n          <p>Excavation volume: ${h.toFixed(2)} cubic yards</p>\n          <p>Base gravel: ${f.toFixed(2)} cubic yards</p>\n          <p>Excavation cost: $${C.toFixed(0)}</p>\n          <p>Base gravel cost: $${k.toFixed(0)}</p>\n        </div>\n        \n        <div class="result-drainage">\n          <h4>Drainage System:</h4>\n          <p>Backfill gravel: ${m.toFixed(2)} cubic yards</p>\n          <p>Drainage pipe: ${x} linear feet (4" perforated)</p>\n          <p>Landscape fabric: ${F.toFixed(1)} sq ft</p>\n          <p>Backfill cost: $${E.toFixed(0)}</p>\n          <p>Pipe cost: $${w.toFixed(0)}</p>\n          <p>Fabric cost: $${B.toFixed(0)}</p>\n        </div>\n        \n        <div class="result-costs">\n          <h4>Total Project Cost:</h4>\n          <p>Materials: $${q.toFixed(0)}</p>\n          <p>Excavation: $${C.toFixed(0)}</p>\n          ${L?`<p>Engineering: $${T.toFixed(0)}</p>`:""}\n          <p>Professional labor: $${M.toFixed(0)}</p>\n          <p><strong>Total DIY cost: $${D.toFixed(0)}</strong></p>\n          <p><strong>Total with labor: $${(D+M+T).toFixed(0)}</strong></p>\n          <p>Cost per sq ft: $${((D+M)/c).toFixed(2)}</p>\n        </div>\n        \n        <div class="result-requirements">\n          <h4>Code & Engineering:</h4>\n          ${L?"<p>⚠️ Engineering required for walls over 3 feet</p>":"<p>✅ No engineering required (under 3 feet)</p>"}\n          <p>Required setback: ${P.toFixed(1)} feet from property line</p>\n          <p>Permit required: ${a>3?"Yes":"Likely not required"}</p>\n          <p>Footing below frost line: ${a>4?"Required":"Recommended"}</p>\n        </div>\n        \n        <div class="result-timeline">\n          <h4>Construction Timeline:</h4>\n          <p><strong>Day 1:</strong> Excavation and base preparation</p>\n          <p><strong>Day 2:</strong> Base gravel and compaction</p>\n          <p><strong>Day 3-4:</strong> Block installation</p>\n          <p><strong>Day 5:</strong> Drainage and backfill</p>\n          <p><strong>Day 6:</strong> Cap blocks and finishing</p>\n          <p>Total labor: ${I.toFixed(1)} hours</p>\n        </div>\n        \n        <div class="result-tools">\n          <h4>Tools & Equipment Needed:</h4>\n          <p>🚜 Mini excavator or hand digging</p>\n          <p>🎢 Plate compactor (rent $75/day)</p>\n          <p>📐 4-foot level and string line</p>\n          <p>🔨 Dead blow hammer</p>\n          <p>🪚 Masonry saw for cuts</p>\n          <p>📏 Measuring tape and chalk line</p>\n        </div>\n        \n        <div class="result-installation">\n          <h4>Installation Steps:</h4>\n          <p>1. Mark utilities and property lines</p>\n          <p>2. Excavate to proper depth and width</p>\n          <p>3. Install and compact base gravel</p>\n          <p>4. Lay first course level and straight</p>\n          <p>5. Install drainage pipe and fabric</p>\n          <p>6. Build wall course by course</p>\n          <p>7. Backfill with drainage gravel</p>\n          <p>8. Install cap blocks and finish grade</p>\n        </div>\n        \n        <div class="result-maintenance">\n          <h4>Long-term Maintenance:</h4>\n          <p>🔍 Annual inspection for settling or movement</p>\n          <p>💧 Check drainage outlets for clogs</p>\n          <p>🌱 Control vegetation on wall face</p>\n          <p>❄️ Monitor for frost damage in cold climates</p>\n          <p>🔧 Address any shifting blocks immediately</p>\n        </div>\n        \n        <div class="result-tips">\n          <h4>Professional Tips:</h4>\n          <p>📞 Call 811 for utility marking before digging</p>\n          <p>📋 Check local codes and permit requirements</p>\n          <p>🏗️ Consider hiring professionals for walls over 3 feet</p>\n          <p>💧 Ensure proper drainage behind wall</p>\n          <p>📐 Use string lines for straight, level installation</p>\n        </div>\n      `})});